    @DisplayName("bottom() returns empty state")
    void testBottom() {
        IntervalDomain domain = new IntervalDomain();
        IntervalDomain.State bottom = domain.bottom();
        assertTrue(domain.isBottom(bottom));
        assertFalse(domain.entails(bottom, domain.top()));
    }

