        IntervalDomain.Interval interval = joined.constraints.get("x");
        assertNotNull(interval);
        assertTrue(interval.min.compareTo(BigInteger.valueOf(0)) <= 0);
        assertTrue(interval.max.compareTo(BigInteger.valueOf(15)) >= 0);
    }

